pub struct VisiblePillar {pub owner:u32,pub starts:u64,pub until:u64,pub center:Point}
#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize,Deserialize)]
pub struct ForcedMovement {pub started:u64,pub until:u64}
#[derive(Debug,Clone)]
