    }

    #[test]
    fn destination_snap_accepts_blocked_outside_and_barrier_separated_requests() {
        let nav = grid(9, 7, 50., &[31]);
        let circles = [Circle { center: Point { x: 225., z: 125. }, radius: 60. }];
