        let circle = Circle { center: Point { x: 150., z: 150. }, radius: 10. };
        for point in [Point { x: f32::NAN, z: 25. }, Point { x: f32::INFINITY, z: 25. }, Point { x: -0.25, z: 25. }, Point { x: 200., z: 25. }, Point { x: f32::MAX, z: 25. }] {
